public static boolean f(int[][] valores, int n, int m, int x) {
        int i, j, cont, p, q;
        boolean a;
        a = false;
        i = 0;
        while (i <= n && !a) {
            j = 0;
            while (j <= m && !a) {
                if (valores[i][j] == x) {
                    a = true;
                }
                j = j + 1;
            }
            i = i + 1;
        }
        return a;
    }
}
